let text = msg.payload;       // exec stdout 전체
let ip_address = msg.ip_address;
let equipment_id = msg.equipment_id;

let hostUp = 0;
let latency = null;
let status = "이상";
let alive = "False";
let errorMsg = null;

// 1. 정상 (응답 있음)
if (/time=/.test(text)) {
    hostUp = 1;
    status = "정상";
    alive = "True";

    let match = text.match(/time[=<]\s?(\d+\.?\d*)/);
    latency = match ? parseFloat(match[1]) : null;
    errorMsg = null;

    // 2. Unreachable
} else if (/Destination Host Unreachable/i.test(text) || /Network is unreachable/i.test(text)) {
    hostUp = 0;
    status = "이상";
    alive = "False";
    errorMsg = "Unreachable";

    // 3. Timeout
} else if (/100% packet loss/i.test(text)) {
    hostUp = 0;
    status = "이상";
    alive = "False";
    errorMsg = "Timeout";
}

msg.payload = {
    equipment_id,
    ip_address,
    host_up: hostUp,
    latency,          // 숫자 (ms)
    status,
    alive,
    error_message: errorMsg
};

return msg;

