let sitename = msg.sitename;
let facilitytype = msg.facilitytype;
let alarm_msg = msg.alarm_msg || "";
let alarm_start_time = msg.alarm_start_time;
let tagsn = msg.tagsn;


// =======================================
// 1) 수위 번호 추출 (없으면 단일 수위)
// =======================================
let levelNum = null;
let isSingleLevel = false;

let m = alarm_msg.match(/수위\s*#?\s*(\d+)|(\d+)\s*지\s*수위/);
if (m) {
  levelNum = m[1] || m[2];
} else {
  isSingleLevel = true; // 번호 없는 단일 수위
}

// =======================================
// 2) 배수지 처리
// =======================================
if (facilitytype === '배수지') {

  // 수위 조건 분기
  let levelCondition = "";
  if (isSingleLevel) {
    // 번호 없는 배수지 수위 (ex: 천의리(배) 수위)
    levelCondition = `
            AND datadesc ILIKE '%수위%'
            AND datadesc !~ '\\d'
        `;
  } else {
    // 번호 있는 수위 (ex: 수위1, 1지 수위)
    levelCondition = `
            AND datadesc ILIKE '%수위%'
            AND datadesc ~ '${levelNum}'
        `;
  }

  let sql = `
WITH target_tags AS (
    SELECT tagsn, datainfo, datadesc
    FROM tb_tag_info
    WHERE sitename = '${sitename}'
      AND facilitytype = '${facilitytype}'
      AND equipmenttype = '수위계'
      AND tagtype = 'Analog Input'
      ${levelCondition}
),
range_data AS (
    SELECT t.tagsn, MAX(r.val) AS max_val, MIN(r.val) AS min_val
    FROM tb_tag_raw_data r
    JOIN target_tags t ON t.tagsn = r.tagsn
    WHERE r.logtime >= now() - interval '5 minutes'
    GROUP BY t.tagsn
)
SELECT 
    '${sitename}' AS sitename,
    '${facilitytype}' AS facilitytype,
    r.tagsn,
    t.datainfo,
    t.datadesc,
    ROUND(r.max_val::numeric, 2) AS max_val,
    ROUND(r.min_val::numeric, 2) AS min_val,
    CASE 
        WHEN r.min_val > 0 
             AND ((r.max_val - r.min_val) / r.min_val * 100) >= 10 
        THEN 'Y' 
        ELSE 'N' 
    END AS hunting_detected
FROM range_data r
JOIN target_tags t ON t.tagsn = r.tagsn;
`;

  msg.topic = sql;
  return msg;
}

