//    → 없으면 단일 수위로 처리
// ------------------------------------------------------
let m = alarm_msg.match(/수위\s*#?\s*(\d+)|(\d+)\s*지\s*수위/);
let levelNum = m ? (m[1] || m[2]) : null;

// 번호 유무에 따른 수위 타입
let levelKey = levelNum ? `수위${levelNum}` : "수위";

// ------------------------------------------------------
// 2) 디지털 알람(item) 자체에서 LL / HH 판정
// ------------------------------------------------------
let levelType = "None";

if (/LL/i.test(alarm_msg)) {
  levelType = "LL";
} else if (/HH/i.test(alarm_msg)) {
  levelType = "HH";
}

// ------------------------------------------------------
// 3) 헌팅 반영
//    - 헌팅 Y → 정상
//    - 헌팅 N → 알람 레벨 유지
// ------------------------------------------------------
msg.check = (hunting === "N") ? levelType : "헌팅 Y (정상)";

