// 4) 결과 저장
// ------------------------------------------------------
msg.hunting = hunting;
msg.levelType = levelType;
msg.levelKey = levelKey;   // 단일 수위면 "수위", 번호 있으면 "수위N"
msg.result = msg.check;

return msg;

