    return null;
}

// 🔹 유량 태그 + 면적 + zone 정보 확인 SQL
let sql = `
WITH flow_tag_check AS (
    SELECT
        COUNT(*) FILTER (WHERE datainfo LIKE '%유입%') AS inflow_cnt,
        COUNT(*) FILTER (WHERE datainfo LIKE '%유출%') AS outflow_cnt
    FROM tb_tag_info
    WHERE sitename = '${sitename}'
      AND facilitytype = '배수지'
      AND tagtype = 'Analog Input'
      AND datainfo LIKE '%유량%'
),
area_info AS (
    SELECT
        zone_1_area,
        zone_2_area,
        zone_3_area,
        zone_4_area,
        zone_5_area,
        COALESCE(zone_1_area,0)
      + COALESCE(zone_2_area,0)
      + COALESCE(zone_3_area,0)
      + COALESCE(zone_4_area,0)
      + COALESCE(zone_5_area,0) AS total_area
    FROM tb_service_reservoir_info
    WHERE sitename = '${sitename}'
)
SELECT
    '${sitename}' AS sitename,

    -- 유량 태그 존재 여부
    CASE
        WHEN f.inflow_cnt > 0 AND f.outflow_cnt > 0
        THEN true ELSE false
    END AS has_flow_tags,

    -- 면적 정보 존재 여부
    CASE
        WHEN a.total_area > 0
        THEN true ELSE false
    END AS has_area_info,

    f.inflow_cnt,
    f.outflow_cnt,

    -- 🔑 zone 정보 전부 내려줌
    a.zone_1_area,
    a.zone_2_area,
    a.zone_3_area,
    a.zone_4_area,
    a.zone_5_area,
    a.total_area

FROM flow_tag_check f
LEFT JOIN area_info a ON true;
`;

