// ========================================
// 1. 단일 알람 객체 입력
// ========================================
let sitename = msg.sitename;
let facilitytype = msg.facilitytype;
let jsDate = msg.alarm_start_time;
let alarm_msg = msg.alarm_msg || "";

// timestamp 문자열 변환
let alarm_start_time = jsDate
    .toISOString()
    .replace('T', ' ')
    .replace('Z', '')
    .slice(0, 23);

// ========================================
// 2. 수위 번호 추출 (지별 수위 판단)
// ========================================
let levelNum = null;
let isSingleLevel = false;

// 예: "수위1", "수위 #1", "1지 수위"
let m = alarm_msg.match(/수위\s*#?\s*(\d+)|(\d+)\s*지\s*수위/);
if (m) {
    levelNum = m[1] || m[2];
} else {
    isSingleLevel = true; // 번호 없는 단일 수위
}

// ========================================
// 3. 필수값 체크
// ========================================
if (!sitename || facilitytype !== '배수지' || !alarm_start_time) {
    node.warn("수위 헌팅 판정 필수 정보 누락");
    return null;
}

// ========================================
// 4. 초경량 운영용 SQL (지별 수위 + 지별 면적)
// ========================================
let sql = `
WITH alarm_time AS (
    SELECT '${alarm_start_time}'::timestamp AS t
),


level_tag AS (
    SELECT tagsn
    FROM tb_tag_info
    WHERE sitename = '${sitename}'
      AND facilitytype = '배수지'
      AND equipmenttype = '수위계'
      AND tagtype = 'Analog Input'
      ${
        isSingleLevel
        ? `AND datadesc ILIKE '%수위%' AND datadesc !~ '\\\\d'`
        : `AND datadesc ILIKE '%수위%' AND datadesc ~ '${levelNum}'`
      }
    ORDER BY tagsn
    LIMIT 1
),

level AS (
    SELECT
        (SELECT r.val
         FROM tb_tag_raw_data r, alarm_time a
         WHERE r.tagsn = lt.tagsn
           AND r.logtime <= a.t
         ORDER BY r.logtime DESC
         LIMIT 1) AS level_now,

        (SELECT r.val
         FROM tb_tag_raw_data r, alarm_time a
         WHERE r.tagsn = lt.tagsn
           AND r.logtime <= a.t - interval '5 minutes'
         ORDER BY r.logtime DESC
         LIMIT 1) AS level_prev
    FROM level_tag lt
),


flow_tags AS (
    SELECT
        MAX(CASE WHEN datainfo LIKE '%유입%유량적산%' THEN tagsn END)  AS in_tagsn,
        MAX(CASE WHEN datainfo LIKE '%유출%유량적산%' THEN tagsn END) AS out_tagsn
    FROM tb_tag_info
    WHERE sitename = '${sitename}'
      AND facilitytype = '배수지'
),


flow AS (
    SELECT
        (SELECT r.val FROM tb_tag_raw_data r, alarm_time a
         WHERE r.tagsn = ft.in_tagsn
           AND r.logtime <= a.t
         ORDER BY r.logtime DESC LIMIT 1) AS acc_in_now,

        (SELECT r.val FROM tb_tag_raw_data r, alarm_time a
         WHERE r.tagsn = ft.in_tagsn
           AND r.logtime <= a.t - interval '5 minutes'
         ORDER BY r.logtime DESC LIMIT 1) AS acc_in_prev,

        (SELECT r.val FROM tb_tag_raw_data r, alarm_time a
         WHERE r.tagsn = ft.out_tagsn
           AND r.logtime <= a.t
         ORDER BY r.logtime DESC LIMIT 1) AS acc_out_now,

        (SELECT r.val FROM tb_tag_raw_data r, alarm_time a
         WHERE r.tagsn = ft.out_tagsn
           AND r.logtime <= a.t - interval '5 minutes'
         ORDER BY r.logtime DESC LIMIT 1) AS acc_out_prev
    FROM flow_tags ft
),


area AS (
    SELECT
        zone_1_area,
        zone_2_area,
        zone_3_area,
        zone_4_area,
        zone_5_area,
        COALESCE(zone_1_area,0)
      + COALESCE(zone_2_area,0)
      + COALESCE(zone_3_area,0)
      + COALESCE(zone_4_area,0)
      + COALESCE(zone_5_area,0) AS total_area
    FROM tb_service_reservoir_info
    WHERE sitename = '${sitename}'
)

-- =====================================
-- 최종 결과
-- =====================================
SELECT
    l.level_now,
    l.level_prev,
    f.acc_in_now,
    f.acc_in_prev,
    f.acc_out_now,
    f.acc_out_prev,
    a.zone_1_area,
    a.zone_2_area,
    a.zone_3_area,
    a.zone_4_area,
    a.zone_5_area,
    a.total_area
FROM level l
CROSS JOIN flow f
CROSS JOIN area a;
`;

