    node.warn("수위/면적 데이터 부족으로 헌팅 판정 불가");
    return null;
}

// ========================================
// 1) 실제 수위 변화
// ========================================
let delta_h_diff = level_now - level_prev;

// ========================================
// 2) 적산 기반 예측 수위 변화
// ========================================
let delta_h_pred =
    ((acc_in_now - acc_in_prev)
        - (acc_out_now - acc_out_prev)) / area_used;

// ========================================
// 3) 🔥 임시 민감 헌팅 판정 로직
// ========================================
let hunting_detected = 'N';
let reason = '물리 예측 범위 내';

// 고정 최소 변화 기준 (테스트용)
let MIN_CHANGE = 0.02;

// 예측이 거의 0인데 실제 변화가 있으면 바로 헌팅
if (Math.abs(delta_h_pred) < 0.001) {
    if (Math.abs(delta_h_diff) > MIN_CHANGE) {
        hunting_detected = 'Y';
        reason = '예측 0 근접 + 실제 수위 변화 발생';
    } else {
        hunting_detected = 'N';
        reason = '예측 및 실제 변화 미미';
    }
} else {

    // 🔥 임계값 대폭 완화 (1.5 → 0.7)
    let threshold = 0.7 * Math.abs(delta_h_pred);

    if (Math.abs(delta_h_diff) >= threshold ||
        Math.abs(delta_h_diff) > MIN_CHANGE) {

        hunting_detected = 'Y';
        reason = '실측 수위 변화가 예측 대비 과도 (민감모드)';
    }
}

// ========================================
// 4) 결과 정리
// ========================================
msg.payload[0] = {
    level_now,
    level_prev,

    delta_h_diff: Number(delta_h_diff.toFixed(3)),
    delta_h_pred: Number(delta_h_pred.toFixed(3)),

    area_used,
    level_type: isSingleLevel ? '단일수위' : `${levelNum}지 수위`,

    hunting_detected,
    판단사유: reason
};

return msg;

