}

let inflow = Number(msg.flow.avg_inflow);   // m3/h
let outflow = Number(msg.flow.avg_outflow);  // m3/h

// 2. 지 파라미터
let zoneArea = Number(zone.zone_area);
let zoneHeight = Number(zone.zone_height);
let hhLevel = Number(zone.hh_level);

// 숫자 검증
if ([inflow, outflow, zoneArea, zoneHeight, hhLevel].some(v => isNaN(v))) {
  msg.payload = {
    error: "숫자 변환 실패",
    inflow, outflow, zoneArea, zoneHeight, hhLevel
  };
  return msg;
}

// 3. 계산
let netFlow = inflow - outflow;
let remainingVolume = (zoneHeight - hhLevel) * zoneArea;

// 4. 결과 객체
let result = {
  sitename: zone.sitename,
  levelNum: Number(msg.levelNum),

  inflow_m3h: inflow,
  outflow_m3h: outflow,
  net_flow_m3h: +netFlow.toFixed(2),

  remaining_volume_m3: +remainingVolume.toFixed(2),
  overflow_eta_hours: null,

  status: "",
  message: ""   // ⭐ 운영 메시지
};

// -------------------------------
// 5. ETA 판단
// -------------------------------
if (netFlow <= 0) {
  result.status = "정상 예정";
}
else if (remainingVolume <= 0) {
  result.status = "오버플로우";
  result.overflow_eta_hours = 0;
}
else {
  result.status = "오버플로우 임박";
  result.overflow_eta_hours = +(remainingVolume / netFlow).toFixed(2);
}

// -------------------------------
// 6. 운영 메시지 생성 (요청 반영)
// -------------------------------

let pumpName = msg.pump_name || "해당";   // 가압장명 (없으면 '해당')

// CASE A : 정상 예정
if (result.status === "정상 예정") {
  result.message =
    `현재 유입량이 유출량보다 적어 대응은 불필요하며 `
  + `일정 시간 이내 가압장 펌프 수동운전(정지)`;
}

// CASE C : 이미 오버플로우
else if (result.status === "오버플로우") {
  result.message =
    `현재 배수지 오버플로우로 판단되며 `
    + `즉시 ${pumpName} 가압장 펌프 수동운전(정지)`;
}

// CASE B : 오버플로우 임박
else if (result.status === "오버플로우 임박") {
  let eta = result.overflow_eta_hours;
  result.message =
    `배수지 오버플로우까지 남은 시간 ${eta}시간으로 판단되며 `
    + `${eta}시간 이내 ${pumpName} 가압장 펌프 수동운전(정지)`;
}


let action_plan = result.message;
let sitename = msg.sitename;
let facility = msg.facility;

// ✅ SQL 완성 (대괄호 없음, 문자열 완전 치환)
// SQL 생성
msg.payload = `
UPDATE tb_equipment_alarm_report
SET     
    countermeasure = '${action_plan}',
    alarm_category = '수위',    
    diagnosed_cause = '펌프검증중'
WHERE sitename = '${sitename}'
  AND facilitytype = '${facility}'
  AND equipmenttype='수위계'
  and alarm_severity is null;
`;


return msg;

// =======================================
// 수위 헌팅 종합 판정
// =======================================

// 입력: msg.payload = 배열
let rows = msg.payload;

if (!Array.isArray(rows) || rows.length === 0) {
  msg.payload = { error: "데이터 없음" };
  return msg;
}

// hunting_detected 값 수집
let huntingList = rows.map(r => r.hunting_detected);

// 하나라도 Y가 있는지
let hasHunting = huntingList.includes("Y");

// 헌팅 태그 목록
let huntingTags = rows
  .filter(r => r.hunting_detected === "Y")
  .map(r => ({
    datainfo: r.datainfo,
    tagsn: r.tagsn
  }));

// 결과
let result = {
  sitename: rows[0].sitename,
  facilitytype: rows[0].facilitytype,
  total_count: rows.length,
  hunting_count: huntingTags.length,
  status: hasHunting ? "헌팅 발생" : "정상",
  hunting_detected: hasHunting ? "Y" : "N",
  hunting_tags: huntingTags
};


msg.payload = result;
return msg;

// ========================================
// PostgreSQL 결과 정리
// ========================================
let row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;

if (!row) {
    node.warn("수위 헌팅 판정 데이터 없음");
    return null;
}

// ========================================
// 수위 번호 / 단일 여부 (이전 Function에서 전달됨)
// ========================================
let levelNum = msg.levelNum;          // 예: 1, 2, ...
let isSingleLevel = msg.isSingleLevel; // true / false

// ========================================
// 값 추출
// ========================================
let level_now  = Number(row.level_now);
let level_prev = Number(row.level_prev);

let acc_in_now   = Number(row.acc_in_now);
let acc_in_prev  = Number(row.acc_in_prev);
let acc_out_now  = Number(row.acc_out_now);
let acc_out_prev = Number(row.acc_out_prev);

// ========================================
// 면적 선택 (핵심 수정)
// ========================================
let area_used = null;

if (isSingleLevel) {
    area_used = Number(row.total_area);
} else {
    let zoneKey = `zone_${levelNum}_area`;
    area_used = Number(row[zoneKey]);
}

// ========================================
// 유효성 체크
// ========================================
if (
    isNaN(level_now) || isNaN(level_prev) ||
    isNaN(area_used) || area_used <= 0
) {
    node.warn("수위/면적 데이터 부족으로 헌팅 판정 불가");
    // node.warn(msg.alarm_msg);
    // node.warn(msg.levelNum);
    return null;
}

// ========================================
// 1) 실제 수위 변화
// ========================================
let delta_h_diff = level_now - level_prev;

// ========================================
// 2) 적산 기반 예측 수위 변화 (지별 면적)
// ========================================
let delta_h_pred =
    ((acc_in_now - acc_in_prev)
   - (acc_out_now - acc_out_prev)) / area_used;

// ========================================
// 3) 헌팅 판정 로직 (물리식 기준)
// ========================================
let hunting_detected = 'N';
let reason = '물리 예측 범위 내';

// 예측값이 거의 0이면 판단 보류
if (Math.abs(delta_h_pred) < 0.001) {
    hunting_detected = 'N';
    reason = '예측 수위 변화 미미';
} else {
    let threshold = 1.5 * Math.abs(delta_h_pred);

    if (Math.abs(delta_h_diff) >= threshold) {
        hunting_detected = 'Y';
        reason = '실측 수위 변화가 물리 예측 대비 과도';
    }
}

// ========================================
// 4) 결과 정리
// ========================================
msg.payload[0] = {
    level_now,
    level_prev,

    delta_h_diff: Number(delta_h_diff.toFixed(3)),
    delta_h_pred: Number(delta_h_pred.toFixed(3)),

    area_used,
    level_type: isSingleLevel ? '단일수위' : `${levelNum}지 수위`,

    hunting_detected,
    판단사유: reason
};

return msg;

