if (upstream_type === 'reservoir') {
    sql = `
    WITH reservoir_ll AS (
        SELECT COALESCE(
            (SELECT CASE
                WHEN AVG(r.val::numeric) <= COALESCE(
                    (SELECT r2.val::numeric FROM tb_tag_info i2
                     JOIN LATERAL (SELECT val FROM tb_tag_raw_data r2
                         WHERE r2.tagsn = i2.tagsn ORDER BY logtime DESC LIMIT 1
                     ) r2 ON true
                     WHERE i2.sitename = '${us}' AND i2.facilitytype = '${uf}'
                       AND i2.datainfo ~* 'LL.*SET|LL.*설정' AND i2.tagtype = 'Analog Output'
                     LIMIT 1), 0)
                THEN true ELSE false
             END
             FROM tb_tag_raw_data r
             JOIN tb_tag_info i ON i.tagsn = r.tagsn
             WHERE i.sitename = '${us}' AND i.facilitytype = '${uf}'
               AND i.equipmenttype = '수위계' AND i.tagtype = 'Analog Input'
               AND r.logtime >= now() - interval '5 minutes'
            ), false
        ) AS upstream_reservoir_ll
    ),
    outlet_valve AS (
        SELECT COALESCE(
            (SELECT CASE WHEN r.val::int = 1 THEN 'open' ELSE 'flt_or_close' END
             FROM tb_tag_info i
             JOIN LATERAL (SELECT val FROM tb_tag_raw_data r
                 WHERE r.tagsn = i.tagsn ORDER BY logtime DESC LIMIT 1
             ) r ON true
             WHERE i.sitename = '${us}' AND i.facilitytype = '${uf}'
               AND i.equipmenttype = '유출밸브'
               AND (i.datainfo ~* 'FULL OPEN|F_OPEN' OR i.datadesc ~* 'F_OPEN|FULL OPEN')
               AND i.tagtype = 'Digital Input'
             LIMIT 1),
            'open'
        ) AS upstream_reservoir_outlet_valve
    )
    SELECT r.upstream_reservoir_ll, o.upstream_reservoir_outlet_valve,
           'normal'::text AS prv_downstream_pressure_status,
           'normal'::text AS prv_other_equipment_holding,
           'normal'::text AS prv_valve_status,
           1.0::float AS block_flow_ratio
    FROM reservoir_ll r, outlet_valve o;
    `;
} else if (upstream_type === 'prv') {
    sql = `
    WITH prv_pressure AS (
        SELECT COALESCE(
            (SELECT CASE
                WHEN AVG(r.val::numeric) < COALESCE(
                    (SELECT r2.val::numeric FROM tb_tag_info i2
                     JOIN LATERAL (SELECT val FROM tb_tag_raw_data r2
                         WHERE r2.tagsn = i2.tagsn ORDER BY logtime DESC LIMIT 1
                     ) r2 ON true
                     WHERE i2.sitename = '${us}' AND i2.facilitytype = '${uf}'
                       AND i2.datainfo ~* '후단.*압력.*LL.*SET|압력.*LL.*SET'
                       AND i2.tagtype = 'Analog Output'
                     LIMIT 1), 0)
                THEN 'low' ELSE 'normal'
             END
             FROM tb_tag_raw_data r
             JOIN tb_tag_info i ON i.tagsn = r.tagsn
             WHERE i.sitename = '${us}' AND i.facilitytype = '${uf}'
               AND i.equipmenttype = '압력계'
               AND i.datainfo ~* '후단|2차'
               AND i.tagtype = 'Analog Input'
               AND r.logtime >= now() - interval '5 minutes'
            ), 'normal'
        ) AS prv_downstream_pressure_status
    ),
    prv_valve AS (
        SELECT COALESCE(
            (SELECT CASE WHEN r.val::int = 1 THEN 'flt' ELSE 'normal' END
             FROM tb_tag_info i
             JOIN LATERAL (SELECT val FROM tb_tag_raw_data r
                 WHERE r.tagsn = i.tagsn ORDER BY logtime DESC LIMIT 1
             ) r ON true
             WHERE i.sitename = '${us}' AND i.facilitytype = '${uf}'
               AND i.datainfo ~* '감압.*밸브.*FLT|감압.*밸브.*FAULT|감압.*밸브.*고장'
               AND i.tagtype = 'Digital Input'
             LIMIT 1),
            'normal'
        ) AS prv_valve_status
    ),
    prv_holding AS (
        SELECT COALESCE(
            (SELECT CASE
                WHEN COUNT(DISTINCT r.val::numeric) <= 1 THEN 'holding'
                ELSE 'normal'
             END
             FROM tb_tag_raw_data r
             JOIN tb_tag_info i ON i.tagsn = r.tagsn
             WHERE i.sitename = '${us}' AND i.facilitytype = '${uf}'
               AND i.equipmenttype ~ '압력계|감압밸브'
               AND r.logtime >= now() - interval '30 minutes'
            ), 'normal'
        ) AS prv_other_equipment_holding
    )
    SELECT false AS upstream_reservoir_ll,
           'open'::text AS upstream_reservoir_outlet_valve,
           pp.prv_downstream_pressure_status,
           ph.prv_other_equipment_holding,
           pv.prv_valve_status,
           1.0::float AS block_flow_ratio
    FROM prv_pressure pp, prv_holding ph, prv_valve pv;
    `;
