    SELECT false AS upstream_reservoir_ll,
           'open'::text AS upstream_reservoir_outlet_valve,
           'normal'::text AS prv_downstream_pressure_status,
           'normal'::text AS prv_other_equipment_holding,
           'normal'::text AS prv_valve_status,
           COALESCE(
               (SELECT AVG(r.val::numeric) / NULLIF(
                   (SELECT AVG(r2.val::numeric) FROM tb_tag_raw_data r2
                    JOIN tb_tag_info i2 ON i2.tagsn = r2.tagsn
                    WHERE i2.sitename = '${us}' AND i2.facilitytype = '${uf}'
                      AND i2.datainfo ~* '유량'
                      AND i2.tagtype = 'Analog Input'
                      AND r2.logtime >= now() - interval '24 hours'
                      AND r2.logtime < now() - interval '1 hour'), 0)
