let sql = `
WITH s AS (
    SELECT
        r.logtime,
        r.val,
        r.val - LAG(r.val) OVER (ORDER BY r.logtime) AS dp
    FROM tb_tag_raw_data r
    WHERE r.tagsn = '${tagsn}'
      AND r.logtime >= now() - interval '4 minutes'
),
d AS (
    SELECT
        logtime,
        dp,
        ABS(dp) AS abs_dp,
        LAG(ABS(dp)) OVER (ORDER BY logtime) AS prev_abs_dp,
        SIGN(dp) AS sign,
        LAG(SIGN(dp)) OVER (ORDER BY logtime) AS prev_sign
    FROM s
    WHERE dp IS NOT NULL
),
eval AS (
    SELECT
        MAX(
            CASE
                WHEN prev_abs_dp > 0
                 AND abs_dp / prev_abs_dp >= 2
                THEN 1 ELSE 0
            END
        ) AS cond1,
        SUM(
            CASE
                WHEN sign * prev_sign = -1
                THEN 1 ELSE 0
            END
        ) AS sign_flip_count
    FROM d
    WHERE logtime >= now() - interval '3 minutes'
)
SELECT
    '${sitename}'   AS sitename,
    '${facilitytype}' AS facilitytype,
    '${tagsn}'      AS tagsn,
    cond1,
    sign_flip_count,
    CASE
        WHEN cond1 = 1 AND sign_flip_count >= 2
        THEN 'Y'
        ELSE 'N'
    END AS hunting_detected
FROM eval;
`;

