 ********************************************/
let alarm_msg = msg.alarm_msg || "";

// 수위 번호 추출: "1지", "수위#1", "수위1", "수위 2"
let m =
    alarm_msg.match(/(\d+)\s*지/) ||
    alarm_msg.match(/수위\s*#?\s*(\d+)/);

let levelNo = null;
let isRepresentative = false;

if (m) {
    levelNo = m[1];
} else {
    isRepresentative = true;
}

// 세분류 추출: 생활용수, 공업용수, 생활, 공업
let subdivision = null;
let subM = alarm_msg.match(/(생활용수|공업용수|생활|공업)/);
if (subM) {
    subdivision = subM[1];
}

msg.level_no = levelNo;
msg.is_representative_level = isRepresentative;
msg._subdivision = subdivision;

/********************************************
 * 2. 같은 시설의 모든 Analog Input 수위 태그 + 최신값 조회
 *    설정값/알람 관련 태그는 제외
 ********************************************/
msg.payload = `
SELECT t.tagsn, t.datainfo, r.val AS level_value, r.logtime
FROM tb_tag_info t
JOIN LATERAL (
    SELECT val, logtime
    FROM tb_tag_raw_data
    WHERE tagsn = t.tagsn
    ORDER BY logtime DESC
    LIMIT 1
) r ON TRUE
WHERE t.sitename = '${msg.sitename}'
  AND t.facilitytype = '${msg.facilitytype}'
  AND t.tagtype = 'Analog Input'
  AND t.equipmenttype = '수위계'
  AND t.datainfo NOT LIKE '%설정값%'
  AND t.datainfo NOT LIKE '%알람%'
  AND t.datainfo NOT LIKE '%스위치%'
  AND t.datainfo NOT LIKE '%염소%'
ORDER BY t.datainfo
`;

return msg;

/********************************************
 * Analog Input 조회 결과에서 알람에 해당하는 태그 매칭
 * - 수위N, N지수위, 생활/공업 세분류 등 모든 패턴 처리
 ********************************************/
let rows = msg.payload;
if (!rows || rows.length === 0) {
    node.warn("아날로그 수위 태그 조회 결과 없음: " + msg.sitename + " " + msg.facilitytype);
    return msg;
}

let levelNo = msg.level_no;
let subdivision = msg._subdivision;
let matched = null;

if (levelNo) {
    /*** 번호가 있는 경우: levelNo에 해당하는 태그 찾기 ***/
    for (const row of rows) {
        const di = row.datainfo || '';

        let hasLevel = false;

        // "N지 수위", "N지수위", "N지수위계"
        let re1 = new RegExp(levelNo + '\\s*지\\s*수위');
        if (re1.test(di)) hasLevel = true;

        // "수위N", "수위 N", "수위#N" (뒤에 다른 숫자 없어야 함)
        let re2 = new RegExp('수위\\s*#?\\s*' + levelNo + '([^0-9]|$)');
        if (re2.test(di)) hasLevel = true;

        if (!hasLevel) continue;

        // 세분류 매칭
        if (subdivision) {
            let subBase = subdivision.replace('용수', '');
            if (di.includes(subBase)) {
                matched = row;
                break;
            }
        } else {
            if (!matched) matched = row;
            if (!di.includes('생활') && !di.includes('공업')) {
                matched = row;
                break;
            }
        }
    }
} else {
    /*** 번호 없는 대표 수위 ***/
    for (const row of rows) {
        const di = (row.datainfo || '').trim();

        // 사이트명(X) 부분 제거 후 숫자 없고 수위/수위계로 끝나는 것
        let cleaned = di.replace(/^[^)]*\)\s*/, '');
        let isPlain = /수위(계)?$/.test(cleaned) && !/\d/.test(cleaned);

        if (isPlain) {
            if (subdivision) {
                let subBase = subdivision.replace('용수', '');
                if (di.includes(subBase)) { matched = row; break; }
            } else {
                if (!di.includes('생활') && !di.includes('공업')) {
                    matched = row;
                    break;
                }
                if (!matched) matched = row;
            }
        }
    }
    if (!matched && rows.length > 0) {
        matched = rows[0];
    }
}

if (!matched) {
    node.warn("매칭 실패: levelNo=" + levelNo + " sub=" + subdivision + " tags=" + rows.map(r=>r.datainfo).join(', '));
    return msg;
}

msg.alarm_value = Number(matched.level_value);
node.warn("아날로그 매칭 성공: " + matched.datainfo + " → " + msg.alarm_value);

return msg;

msg.payload = `
SELECT service_area
FROM tb_service_reservoir_info
WHERE sitename = '${msg.sitename}';
`;
return msg;

if (Array.isArray(msg.payload) && msg.payload.length > 0) {
    msg.service_area = msg.payload[0].service_area;
} else {
    msg.service_area = undefined;
}
return msg;

// 예상피해: expected_impact_assessment 직접 사용
if (msg.expected_impact_assessment) {
    msg.text_expected_damage = msg.expected_impact_assessment;
} else {
    msg.text_expected_damage = '예상피해 정보 없음';
}

// 급수지역
if (msg.service_area) {
    msg.text_expect_area = msg.service_area;
} else {
    msg.text_expect_area = '배수지의 시설의 급수지역 정보가 없습니다.';
}

return msg;

function fmtLocal(d) {
  if (!(d instanceof Date) || isNaN(d.getTime())) return "";
  return d.getFullYear() + '-' +
    String(d.getMonth()+1).padStart(2,'0') + '-' +
    String(d.getDate()).padStart(2,'0') + ' ' +
    String(d.getHours()).padStart(2,'0') + ':' +
    String(d.getMinutes()).padStart(2,'0') + ':' +
    String(d.getSeconds()).padStart(2,'0');
}

// payload가 배열이면 첫 요소 사용, 아니면 그대로 사용
let row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;


if (!row) {
    node.error("payload가 비어있음", msg);
    return msg;
}

let original = row.diagnosed_msg || "";

if (!original) {
    node.error("diagnosed_msg가 NULL 또는 빈값입니다.", msg);
    return msg;
}




// 해제시각 HTML
let jeDate = new Date(row.alarm_end_time);
let alarm_end_time = fmtLocal(jeDate);
let text_alarm_end_time = `<li><string><b>알람 해제시각</b>은 ${alarm_end_time} 입니다.</string></li>`;
let jsDate = new Date(row.alarm_start_time);
msg.alarm_start_time = fmtLocal(jsDate);
msg.sitename = row.sitename;
msg.facilitytype = row.facilitytype;
msg.tagsn = row.tagsn;
msg.alarm_category = row.alarm_category || '';
msg.alarm_end_time_str = alarm_end_time;



// "진행중" → "해제완료"
let updated = original.replace(/진행중/g, "알람해제");

// 발생시각 아래 삽입
updated = updated.replace(
    /(<li>\s*<string>\s*<b>발생시각<\/b>[\s\S]*?<\/string>\s*<\/li>)/,
    `$1\n${text_alarm_end_time}`
);

// SQL Escape
msg.diagnosed_msg_sql = updated.replace(/'/g, "''");



return msg;

function fmtLocal(d) {
  if (!(d instanceof Date) || isNaN(d.getTime())) return "";
  return d.getFullYear() + '-' +
    String(d.getMonth()+1).padStart(2,'0') + '-' +
    String(d.getDate()).padStart(2,'0') + ' ' +
    String(d.getHours()).padStart(2,'0') + ':' +
    String(d.getMinutes()).padStart(2,'0') + ':' +
    String(d.getSeconds()).padStart(2,'0');
}

function toPgTimestamp(v) {
  if (!v) return "";
  // JS Date → ISO 8601 → PostgreSQL 호환 포맷 변환
  let d = new Date(v);
  if (isNaN(d.getTime())) return "";

  return fmtLocal(d);
}

// 변환된 값 저장
let jsDate = new Date(msg.alarm_start_time);
let alarm_start_time = fmtLocal(jsDate);



if (msg.alarm_severity === null || msg.alarm_severity === undefined) {
  return;   // 다음 노드로 메시지 안 보내고 종료
}

//----------------------------------------------------------
// 0. 안전 문자열 함수
//----------------------------------------------------------
function safe(v) {
  return (v !== undefined && v !== null) ? String(v) : "";
}

// PostgreSQL용 escape (‘ → ’’)
function esc(v) {
  return safe(v).replace(/'/g, "''");
}

