const diagnosed_cause = '전단 공급설비 유량 80% 미만으로 전단 점검 필요';
const countermeasure = '전단 공급설비 점검 후 이전 배수지/가압장 알고리즘 시행';

msg.payload = `
UPDATE tb_equipment_alarm_report
SET
  diagnosed_cause = '${diagnosed_cause}',
  countermeasure = '${countermeasure}',
  diagnosed_msg = NULL
WHERE sitename = '${sitename}'
  AND facilitytype = '${facilitytype}'
  AND tagsn = '${tagsn}'
  AND alarm_start_time::timestamp(0) = '${alarm_start_time}'::timestamp
  AND countermeasure = '펌프검증중';
`;

return msg;

// tb_alarm_contact → global context 캐시
const cache = {};
for (const row of (msg.payload || [])) {
  if (!cache[row.category]) cache[row.category] = [];
  cache[row.category].push({ company: row.company, phone: row.phone });
}
global.set('alarm_contacts_cache', cache);
node.log('비상연락처 캐시 갱신: ' + Object.keys(cache).map(k => k + '(' + cache[k].length + ')').join(', '));
return null;
